def compute(vars):
    old_compensation = vars["v1"]
    new_compensation = vars["v2"]
    change = new_compensation - old_compensation

    return {
        "value": change,
        "trace": {
            "old_compensation": old_compensation,
            "new_compensation": new_compensation,
            "change": change,
            "output_meta": {
                "currency": "GBP",
                "scale": "million",
                "unit": None
            }
        }
    }
